    STRINGS: STRINGS,
    THEMES: THEME_DEFS,
    GEOMETRY: { W: W, KEY_AREA_H: KEY_AREA_H, STRIP_H: STRIP_H, ROW_PITCH: ROW_PITCH, KEY_H: KEY_H, TOP_PAD: TOP_PAD, BOTTOM_PAD: BOTTOM_PAD, V_GAP: V_GAP, H_GAP: H_GAP },
